package com.novasoft.psicoapp.controller;
import com.novasoft.psicoapp.model.*; import com.novasoft.psicoapp.repo.*; import com.novasoft.psicoapp.service.CurrentUser; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/academic") public class AcademicController{ private final CourseRepo courses; private final GroupRepo groups; private final UserRepo users; private final CurrentUser current; public AcademicController(CourseRepo c,GroupRepo g,UserRepo u,CurrentUser cu){courses=c;groups=g;users=u;current=cu;} @GetMapping("/courses") public List<Course> courses(){return courses.findAll();} @PostMapping("/courses") @PreAuthorize("hasAnyRole('PROFESOR','ADMIN')") public Course course(@RequestBody Course c){c.professor=current.get(); return courses.save(c);} @GetMapping("/groups") public List<StudyGroup> groups(){return groups.findAll();} @PostMapping("/groups") @PreAuthorize("hasAnyRole('PROFESOR','ADMIN')") public StudyGroup group(@RequestBody Map<String,Object> b){StudyGroup g=new StudyGroup(); g.name=(String)b.get("name"); g.course=courses.findById(Long.valueOf(b.get("courseId").toString())).orElseThrow(); return groups.save(g);} @PostMapping("/groups/{id}/students/{studentId}") @PreAuthorize("hasAnyRole('PROFESOR','ADMIN')") public StudyGroup addStudent(@PathVariable Long id,@PathVariable Long studentId){StudyGroup g=groups.findById(id).orElseThrow(); g.students.add(users.findById(studentId).orElseThrow()); return groups.save(g);} }
